with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الأرصاد الزراعية والتطبيقات المناخية القطاعية','متغيرات الأرصاد الزراعية ومراحل نمو المحاصيل والإجهاد الحراري والمائي والخدمات المناخية والتقويم الزراعي.',35,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأرصاد الزراعية والمحاصيل',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الخدمات المناخية والتطبيقات',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('agrometeorology-scope-and-variables','مقدمة في الأرصاد الزراعية ومتغيراتها','تفاعل الطقس والمناخ مع التربة والمحاصيل والإنتاج.','{"blocks":[{"type":"text","text":"يعرض الدرس مقدمة في الأرصاد الزراعية ومتغيراتها ضمن تطبيقات الأرصاد الجوية والمناخية لدعم القطاع الزراعي."},{"type":"text","text":"الفكرة الأساسية: تفاعل الطقس والمناخ مع التربة والمحاصيل والإنتاج.، ويجب ربط المتغير الجوي بالمرحلة الزراعية والموقع ونوع المحصول."},{"type":"text","text":"تحدد البيانات المطلوبة من محطات الطقس والتربة والمزارع والسجلات الزراعية والمنتجات الفضائية."},{"type":"text","text":"تراجع جودة القياسات ومواقع الحساسات وفترات التجميع قبل بناء المؤشرات أو المقارنات."},{"type":"text","text":"تفسر النتائج وفق نوع التربة والمحصول والمرحلة الفينولوجية والإدارة الزراعية."},{"type":"text","text":"تؤخذ الفروق المحلية في الارتفاع والتعرض والري والغطاء الأرضي في الحسبان عند تعميم النتائج."},{"type":"text","text":"تستخدم المؤشرات والمعادلات ضمن مجال صلاحيتها مع توثيق الوحدات والمعاملات والافتراضات."},{"type":"text","text":"تقارن النتائج بالملاحظات الحقلية أو السجلات المستقلة لتقييم الأداء وعدم اليقين."},{"type":"text","text":"تترجم المخرجات إلى توقيت أو خريطة أو نشرة تساعد المستخدم الزراعي على اتخاذ قرار مناسب."},{"type":"text","text":"يجب الفصل بين المعلومة المناخية والتوصية الزراعية المتخصصة، والتنسيق مع الجهات الفنية المعنية."},{"type":"text","text":"مثال تطبيقي: ربط توقع درجات الحرارة والهطول خلال مرحلة نمو حساسة بخريطة مناطق المحاصيل المعرضة."},{"type":"callout","text":"الخلاصة: الخدمة الأرصادية الزراعية الفعالة تحول البيانات الجوية إلى معلومة قطاعية مفهومة ومحددة الحدود."}]}',3360,55,'["تحديد المتغيرات الجوية والزراعية المؤثرة","تفسير المؤشرات ضمن السياق المحلي","إعداد مخرجات تخدم القرار الزراعي"]','الأرصاد الزراعية والمحاصيل'),
('crop-weather-requirements','الاحتياجات الجوية والمناخية للمحاصيل','الحرارة والضوء والماء ومراحل النمو.','{"blocks":[{"type":"text","text":"يعرض الدرس الاحتياجات الجوية والمناخية للمحاصيل ضمن تطبيقات الأرصاد الجوية والمناخية لدعم القطاع الزراعي."},{"type":"text","text":"الفكرة الأساسية: الحرارة والضوء والماء ومراحل النمو.، ويجب ربط المتغير الجوي بالمرحلة الزراعية والموقع ونوع المحصول."},{"type":"text","text":"تحدد البيانات المطلوبة من محطات الطقس والتربة والمزارع والسجلات الزراعية والمنتجات الفضائية."},{"type":"text","text":"تراجع جودة القياسات ومواقع الحساسات وفترات التجميع قبل بناء المؤشرات أو المقارنات."},{"type":"text","text":"تفسر النتائج وفق نوع التربة والمحصول والمرحلة الفينولوجية والإدارة الزراعية."},{"type":"text","text":"تؤخذ الفروق المحلية في الارتفاع والتعرض والري والغطاء الأرضي في الحسبان عند تعميم النتائج."},{"type":"text","text":"تستخدم المؤشرات والمعادلات ضمن مجال صلاحيتها مع توثيق الوحدات والمعاملات والافتراضات."},{"type":"text","text":"تقارن النتائج بالملاحظات الحقلية أو السجلات المستقلة لتقييم الأداء وعدم اليقين."},{"type":"text","text":"تترجم المخرجات إلى توقيت أو خريطة أو نشرة تساعد المستخدم الزراعي على اتخاذ قرار مناسب."},{"type":"text","text":"يجب الفصل بين المعلومة المناخية والتوصية الزراعية المتخصصة، والتنسيق مع الجهات الفنية المعنية."},{"type":"text","text":"مثال تطبيقي: ربط توقع درجات الحرارة والهطول خلال مرحلة نمو حساسة بخريطة مناطق المحاصيل المعرضة."},{"type":"callout","text":"الخلاصة: الخدمة الأرصادية الزراعية الفعالة تحول البيانات الجوية إلى معلومة قطاعية مفهومة ومحددة الحدود."}]}',3370,55,'["تحديد المتغيرات الجوية والزراعية المؤثرة","تفسير المؤشرات ضمن السياق المحلي","إعداد مخرجات تخدم القرار الزراعي"]','الأرصاد الزراعية والمحاصيل'),
